//! `attend` clap-derive command surface.
//!
//! This module is the canonical source for the runtime `--help` text and
//! the markdown reference at `docs/cli/attend.md` (generated by
//! `bin/gen-docs.rs`). Doc comments here become help strings; edit them
//! in one place and both surfaces update on rebuild. `gen-docs` reads the
//! tree through the library's `cli_command()`.

use crate::describe;
use clap::{Args, Parser, Subcommand};

/// The closing line of a bare `attend` and of `attend --help` (ADR-413 item 4).
const AFTER_HELP: &str = "In a session with the attend mod, the attend_* tools send, reply, join and list peers. This CLI is for hosts without the mod and for scripts.";

#[derive(Parser)]
#[command(
    name = "attend",
    version = concat!(env!("CARGO_PKG_VERSION"), " (", env!("ATTEND_COMMIT"), ")"),
    about = "Active awareness for Claude Code sessions",
    long_about = None,
    after_help = AFTER_HELP,
    disable_help_subcommand = true,
)]
pub(crate) struct Cli {
    #[command(subcommand)]
    pub(crate) command: Option<Commands>,
}

/// The eight top-level commands. The one-release aliases of the old flat
/// verbs were removed by issue #982, and `run` by #1316: awareness reaches
/// a session only through the attend mod.
#[derive(Subcommand)]
pub(crate) enum Commands {
    /// `attend run` is removed (#1316). It stays as a hidden stub for one
    /// release, so an `attend run` an older attend started, which
    /// re-executes into this binary when it updates, or a Monitor that
    /// starts it again, says where awareness went and exits 2.
    // #1316 grace: remove after the next release.
    #[command(hide = true, disable_help_flag = true)]
    Run {
        /// Whatever the old command took, `--catchup` included: ignored.
        #[arg(trailing_var_arg = true, allow_hyphen_values = true, num_args = 0..)]
        rest: Vec<String>,
    },

    #[command(about = describe::LISTEN)]
    Listen {
        #[command(subcommand)]
        sub: Option<ListenCmd>,

        /// Print the state as one JSON document
        #[arg(long, global = true)]
        json: bool,
    },

    /// Send, reply to, read, count and delete messages, and tombstone a session (default: inbox)
    #[command(args_conflicts_with_subcommands = true)]
    Message {
        #[command(flatten)]
        inbox: InboxFlags,

        #[command(subcommand)]
        sub: Option<MessageCmd>,
    },

    /// Join, leave, list and manage channels and scenes (default: list)
    Channel(ChannelGroup),

    /// List sessions, show this session's identity and the running loops (default: list)
    #[command(args_conflicts_with_subcommands = true)]
    Peer {
        #[command(flatten)]
        list: JsonArgs,

        #[command(subcommand)]
        sub: Option<PeerCmd>,
    },

    /// Keep the prompt cache warm across idle stretches (ADR-182; default: status)
    Keepwarm {
        #[command(subcommand)]
        sub: Option<KeepwarmCmd>,
    },

    /// Launch the interactive chat TUI (ADR-120)
    Chat {
        /// Arguments passed through to the `attend-chat` binary
        #[arg(trailing_var_arg = true, allow_hyphen_values = true)]
        passthrough: Vec<String>,
    },

    /// List, poll, probe and test-fire sensors, and audit their permissions (default: list)
    Sensor {
        #[command(subcommand)]
        sub: Option<SensorCmd>,
    },

    /// Manage configuration (default: show)
    Config {
        #[command(subcommand)]
        sub: Option<ConfigCmd>,
    },
}

/// Subcommands for `attend message`. With no subcommand, defaults to `inbox`.
#[derive(Subcommand)]
pub(crate) enum MessageCmd {
    #[command(about = describe::SEND)]
    Send(SendArgs),

    #[command(about = describe::REPLY)]
    Reply(ReplyArgs),

    #[command(about = describe::INBOX)]
    Inbox(InboxArgs),

    #[command(about = describe::UNREAD)]
    Unread(JsonArgs),

    #[command(about = describe::LAPSE)]
    Lapse(LapseArgs),

    // `with_limits` writes this verb's help with the limits it applies.
    /// Reap signal files whose owning project is gone, and prune empty project dirs
    Cleanup(CleanupArgs),

    // `with_limits` writes this verb's long help with the limits it applies.
    /// Mark for deletion the messages no live session still has to read
    Delete(DeleteArgs),

    /// Tombstone a session that has exited, so every reader skips its messages
    ///
    /// The drain, the mod, `attend message unread` and `attend message
    /// inbox` all skip what a tombstoned session sent, and
    /// the drain records it read, up to when it was tombstoned; what the
    /// session sends later, back under --resume, shows. Only an agent's
    /// session that this host saw exit is tombstoned: a person's id, a
    /// session that may still read the bus, an id such a session had
    /// before /clear and this session's own are refused. Its messages stay
    /// on disk; `attend message delete --everywhere --from <id>` marks them
    /// for deletion. --ended tombstones, as one batch, every agent with a
    /// message still shown on the bus that the same rule allows, and
    /// --undo with no session takes the newest batch back.
    Tombstone(TombstoneArgs),
}

/// The help of the verbs that state a limit, written from the constants
/// that set it, so the text cannot drift from the behaviour.
pub(crate) fn with_limits(cmd: clap::Command) -> clap::Command {
    let grace = attend_presence::heartbeat::DEFAULT_GRACE.as_secs();
    let days = crate::cmd::cleanup::MARK_REAP_DAYS;
    let sessions = crate::cmd::cleanup::MARK_REAP_SESSIONS;
    let reap = format!(
        "{days} days after the mark, or for a message in a project tray once that project has started {sessions} \
         Claude Code sessions since, each /clear counting as one"
    );
    let delete = format!(
        "Mark for deletion the messages no live session still has to read\n\n\
         A message is marked when it is in the scope, older than --older-than, older than {grace} seconds, and \
         no session that may still read the bus would be delivered it: a session keeps what `attend message \
         unread` counts for it, its cold start included, and one this host cannot judge keeps its mail while \
         its last heartbeat is under {days} days old. A \
         person in attend-chat holds nothing. Every reader skips a marked message, and `attend message \
         cleanup` removes it {reap} (ADR-404 D3e). --undo takes a delete back, and its messages are delivered \
         again, while cleanup has not yet removed them."
    );
    let cleanup = format!(
        "Reap signal files whose owning project is gone, and prune empty project dirs. Lifetime is bound to \
         project liveness (ADR-136); the one removal by age is of a message `attend message delete` marked, \
         {reap} (ADR-404 D3e)."
    );
    // `mut_subcommands` edits each in place; `mut_subcommand` would move the
    // edited one to the end and reorder the help and the generated docs.
    cmd.mut_subcommands(|top| {
        if top.get_name() != "message" {
            return top;
        }
        top.mut_subcommands(|verb| match verb.get_name() {
            "delete" => verb.about(delete.lines().next().unwrap_or_default().to_string()).long_about(delete.clone()),
            "cleanup" => verb.about(cleanup.clone()),
            _ => verb,
        })
    })
}

/// Subcommands for `attend channel`. With no subcommand, defaults to `list`.
#[derive(Subcommand)]
pub(crate) enum ChannelCmd {
    #[command(about = describe::CHANNELS)]
    List(ChannelListArgs),

    #[command(about = describe::JOIN)]
    Join(JoinArgs),

    /// Add a session to a channel; it is told, and handed the recent history
    ///
    /// The session is enrolled with no answer from it (ADR-404 D1), told
    /// by a direct message to its project, and handed the newest 50 of the
    /// channel's messages to read, as a join answering an invitation is.
    /// Any invitation it had there is spent.
    Add(AddArgs),

    #[command(about = describe::LEAVE)]
    Leave(LeaveArgs),

    /// Create a channel without joining it (pinned so it persists empty)
    Create {
        /// Channel name (with or without the # prefix)
        name: String,
        /// Optional single-line description (all trailing words)
        #[arg(trailing_var_arg = true, allow_hyphen_values = true)]
        description: Vec<String>,
    },

    /// Set or replace a channel's single-line description
    Describe {
        /// Channel name (with or without the # prefix)
        name: String,
        /// The description text (all trailing words; empty clears)
        #[arg(trailing_var_arg = true, allow_hyphen_values = true)]
        description: Vec<String>,
    },

    /// Pin a channel so it persists when empty
    Pin(NameArg),

    /// Unpin a channel; it is removed if empty
    Unpin(NameArg),

    /// Dissolve a channel (removes it for every member)
    Dissolve(NameArg),

    /// Activate a named scene (reconfigure channel membership; `scene private` leaves all channels)
    Scene(SceneArgs),

    /// List available scenes
    Scenes,
}

/// Subcommands for `attend peer`. With no subcommand, defaults to `list`.
#[derive(Subcommand)]
pub(crate) enum PeerCmd {
    #[command(about = describe::PEERS)]
    List(JsonArgs),

    /// Print this session's canonical bus identity (issue #378)
    Whoami(WhoamiArgs),

    #[command(about = describe::STATUS)]
    Status(JsonArgs),
}

/// Subcommands for `attend sensor`. With no subcommand, defaults to `list`.
///
/// Each sensor is a YAML file (ADR-403): shipped with attend, under
/// `$XDG_CONFIG_HOME/attend/sensors/`, or in a project's
/// `.claude/attend/sensors/`, layered by name.
#[derive(Subcommand)]
pub(crate) enum SensorCmd {
    /// List every sensor the files declare, with its kind, origin, file, source and state
    List(JsonArgs),

    /// Run one real poll of a sensor and deliver what its threshold lets through to the session
    Poll(PollArgs),

    /// Send a synthetic result through a sensor's threshold and lane to the session, marked [test]
    Fire(FireArgs),

    /// Call an mcp sensor's tool twice and record whether reading it changed it
    ///
    /// The probe calls the tool twice in a row and checks that the second
    /// call returned every item of the first, by each trigger's key, or for
    /// state triggers the same state. It cannot see read state the service
    /// keeps, such as a message marked read, so it asks you at the terminal
    /// to confirm in another client that the items are untouched; with no
    /// terminal the record says they were not confirmed. From Claude Code,
    /// run it as `! attend sensor probe <name>`. It writes the record as
    /// `probe` in the sensor's user file, created with that field alone
    /// when the sensor has none. An mcp sensor runs only once its record
    /// holds: taken with its server's definition, tool and args, with the
    /// calls matching and confirmed.
    Probe(ProbeArgs),

    /// Compare each sensor's `requires:` against settings.json
    Permissions,

    /// Run one session's sensors and write what they report to it as system signals
    ///
    /// The attend mod starts one host for each listening session and stops
    /// it when the session stops listening. The host polls the sensors the
    /// files declare for --cwd; the peers sensor reports sessions starting
    /// and leaving but no messages.
    /// Each report the governor lets through becomes a signal from
    /// `system:<sensor>` addressed to --session, on the sensor's lane, with
    /// the expiry its trigger sets; the mod delivers it as it delivers a
    /// message. Each signal written prints one line on stdout, `signal
    /// <id>`, and nothing else does; logs go to stderr. A changed binary or
    /// sensor file re-executes the host in place.
    Host(HostArgs),
}

#[derive(Args)]
pub(crate) struct HostArgs {
    /// The session the signals are addressed to
    #[arg(long)]
    pub(crate) session: String,
    /// The session's directory: the project the sensors watch, whose tray
    /// the signals go to
    #[arg(long)]
    pub(crate) cwd: String,
    /// The id the session had before /clear: its sensor stores and the
    /// memory of triggers kept for the session move to --session
    #[arg(long, value_name = "OLD_ID")]
    pub(crate) moved_from: Option<String>,
    /// The process that started the host, Claude Code: the host exits once
    /// it is gone, even when it went before the host could look at its
    /// own parent
    #[arg(long, value_name = "PID")]
    pub(crate) parent: Option<u32>,
}

#[derive(Args)]
pub(crate) struct PollArgs {
    /// The sensor's name
    pub(crate) name: String,
    /// The session whose store the poll reads and to which it delivers;
    /// unset, the session this shell runs in
    #[arg(long, value_name = "ID")]
    pub(crate) session: Option<String>,
    /// Stop before delivery
    #[arg(long)]
    pub(crate) dry_run: bool,
    /// Print the result as one JSON document
    #[arg(long)]
    pub(crate) json: bool,
}

#[derive(Args)]
pub(crate) struct ProbeArgs {
    /// The mcp sensor's name
    pub(crate) name: String,
    /// Print the record as one JSON document
    #[arg(long)]
    pub(crate) json: bool,
}

#[derive(Args)]
pub(crate) struct FireArgs {
    /// The sensor, or `<sensor>/<trigger>` for one trigger
    pub(crate) target: String,
    /// The synthetic result: a file, or `-` for stdin. A command sensor with
    /// `output: json` takes one JSON poll result, which its state and
    /// triggers evaluate. Any other sensor takes a JSON list of `{magnitude,
    /// description}` or `magnitude|description` lines; with none, one
    /// observation at the sensor's threshold
    #[arg(long, value_name = "FILE|-")]
    pub(crate) input: Option<String>,
    /// The session whose store the fire reads and to which it delivers;
    /// unset, the session this shell runs in
    #[arg(long, value_name = "ID")]
    pub(crate) session: Option<String>,
    /// Stop before delivery
    #[arg(long)]
    pub(crate) dry_run: bool,
    /// Keep the trigger memory and declared state the fire leaves; a test
    /// fire writes neither without it
    #[arg(long)]
    pub(crate) commit: bool,
    /// Print the result as one JSON document
    #[arg(long)]
    pub(crate) json: bool,
}

